@startuml

class OilCompany {}
class GasStation {}
class Pump {}
class Reservoir {}
class GasolineType {}
class Customer {}
class RefuelCard {}
class RefuelTurn {}
class MonthlyInvoice {}
class Payment {}
class DailyReport {}

class PumpStatus {
  AVAILABLE
  BLOCKED_CRITICAL
  BLOCKED_REFILLING
}

GasStation "1" -- "*" Pump : possesses
Pump "1" -- "1" Reservoir : has
Pump "1" -- "1" GasolineType : contains
Pump "1" -- "1" PumpStatus : has
Pump "0..1" -- "0..1" Customer : is used by

Customer "1" -- "*" RefuelTurn : performs
Customer "1" -- "0..1" RefuelCard : holds
Customer "1" -- "*" MonthlyInvoice : receives
Customer "1" -- "*" Payment : makes

MonthlyInvoice "1" -- "*" RefuelTurn : includes
MonthlyInvoice "1" -- "0..*" Payment : is settled by

DailyReport ..> Pump : reports on

@enduml

